                    self.retain_and_send(ExecutionPortMessage::ModelChunkMessage(public))
                        .await?;
                }
                Box::pin(self.accept_control(
                    &ExecutionPortMessage::ModelChunkMessage(chunk.clone()),
                    now.clone(),
                ))
                .await
            }
