async fn send_execution_message(
        &mut self,
        message: ExecutionPortMessage,
    ) -> Result<(), WorkerError> {
        if let Some(models) = &mut self.device_models
            && models.send(&message).map_err(|_| codex_model_error())?
        {
            return Ok(());
        }
        self.port
            .send(message)
            .await
            .map_err(|_| execution_port_error())
    }

